						"lower": { "$ref": "#/$defs/weightAggregateNullableValues" },
						"upper": { "$ref": "#/$defs/weightAggregateNullableValues" },
						"sampleCount": { "$ref": "#/$defs/weightAggregateNullableCounts" },
