				"zeroContributorsYieldNull": { "const": true },
				"membershipTimeConversion": { "$ref": "#/$defs/tracePreparationConversionOrNull" },
				"evaluationTimeConversion": { "$ref": "#/$defs/tracePreparationConversionOrNull" },
